/**
 * V36 — LEVANTAMENTO DAS CLÁUSULAS DE CONTABILIDADE (5.9 e 5.10) QUE ESTAVAM NAO_VERIFICADO.
 *
 * 2026-10-05, sobre o commit 9020303e (V35 publicada como 8b63c84). Sete varreduras somente
 * leitura, uma por fatia, cláusula por cláusula contra o código, os testes e os percursos.
 * Cada marca diz o que existe, o que falta, e — quando o sistema faz a mesma coisa por
 * outro caminho (estorno no lugar de alteração, efetivação no lugar de "disponibilizar",
 * cota por fonte no lugar de contingenciamento por percentual) — diz qual caminho e se o
 * efeito é o mesmo. Diferença de nome não rebaixa; diferença de efeito rebaixa.
 *
 * Na dúvida, o nível mais baixo. Onde o percurso que sustentaria a validação está
 * desatualizado (o de adiantamentos é anterior à guarda da devolução da V35), a marca fica
 * em IMPLEMENTADO_NAO_VALIDADO até o percurso rodar de novo.
 */
type Situacao =
  | "NAO_VERIFICADO"
  | "AUSENTE_CONFIRMADO"
  | "PARCIAL"
  | "IMPLEMENTADO_NAO_VALIDADO"
  | "VALIDADO_LOCALMENTE"
  | "DEPENDENCIA_EXTERNA";

interface Marca {
  readonly situacao: Situacao;
  readonly evidencia: string;
  readonly rota_verificada?: string;
}

const V36 = "V36 (levantamento 2026-10-05, commit 9020303e):";

const ROTA_ADIANTAMENTOS =
  "papel: administrador (EMPENHAR) · contexto: next dev na 3011, banco gestao_publica_esperanca_ficticio, 2026-10-05 · passos: /despesa/adiantamentos → conceder diária (destino, 2,5 x 200,00) → controle 7/8 conferido no banco → /transparencia/diarias mostra a diária com CPF mascarado → conceder suprimento → prestação com 50,00 devolvidos → aprovar é recusado com o motivo e nada é gravado → rejeitar com parecer → nova prestação sem devolução → aprovar → a baixa inverte o controle da concessão → prestação da diária aprovada → recarga mostra as duas comprovadas · obtido: 19/19 · artefato: scripts/percurso-v36-adiantamentos.mts.";

function m(situacao: Situacao, evidencia: string, rota?: string): Marca {
  return rota === undefined
    ? { situacao, evidencia: `${V36} ${evidencia}` }
    : { situacao, evidencia: `${V36} ${evidencia}`, rota_verificada: rota };
}

